def date_matches(value,query):
    q=query.lower()
    if q=='none': return not value
    if q=='any': return bool(value)
    if not value: return False
    try: actual=datetime.date.fromisoformat(value)
    except ValueError: return False
    delta=(actual-TODAY).days
    if q=='overdue': return delta<0
    if q=='soon': return delta<=7
    if q in ('today','tomorrow','yesterday'):
        expected={'today':TODAY,'tomorrow':TODAY+datetime.timedelta(days=1),'yesterday':TODAY-datetime.timedelta(days=1)}[q]
        return actual==expected
    try:
        lo,hi,_=dateutil.parse_date_range(q,TODAY)
        return (lo is None or actual>=lo) and (hi is None or actual<=hi)
    except (ValueError,TypeError): return False
def filter_matches(expression,d,use_regex=False):
    sep='~' if '~' in expression or use_regex else '|'
    for rule in expression.split(sep):
        okay=True
        for cond in rule.split(';'):
            if not cond: continue
            negate=cond.startswith('-'); cond=cond[1:] if negate else cond
            name,eq,value=cond.partition('='); name=name.lower(); choices=value.split(',') if eq else ['any']
            vals={'done':['x' if d['done'] else ''],'subj':[d['subject']], 'subject':[d['subject']],
                  'pri':[d['pri'].lower()], 'project':d['projects'], 'prj':d['projects'],
                  'context':d['contexts'], 'ctx':d['contexts'], 'hashtag':re.findall(r'(?<!\S)#([^\s]+)',d['subject']),
                  'created':[d['created']], 'finished':[d['finished']], 'due':[d['due']],
                  'threshold':[d.get('threshold','')], 'thr':[d.get('threshold','')]}.get(name)
            vals=vals if vals is not None else ([v for k,v in d['tags'].items() if k==name])
            flat=[x for x in vals if x]
            found=False
            for choice in choices:
                if choice=='none': found |= not flat; continue
                if choice=='any': found |= bool(flat); continue
                for actual in flat:
                    if '..' in choice:
                        try:
                            lo,hi,_=dateutil.parse_date_range(choice,TODAY)
                            x=datetime.date.fromisoformat(actual)
                            found |= (lo is None or x>=lo) and (hi is None or x<=hi)
                            continue
                        except: pass
                        lo,_,hi=choice.partition('..')
                        try: found |= (not lo or float(actual)>=float(lo)) and (not hi or float(actual)<=float(hi))
                        except: pass
                    elif use_regex:
                        try: found |= re.search(choice,actual,re.I) is not None
                        except re.error: pass
                    else: found |= choice.lower() in actual.lower()
            if negate: found=not found
            if not found: okay=False; break
        if okay: return True
    return False
